import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-11","description":"","frontmatter":{"title":"AI 动态 · 2026-11-11","date":"2026-11-11T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-11.md","filePath":"news/2026-11/ai-news-2026-11-11.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-11.md"};function i(o,e,l,p,c,h){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-11-11" tabindex="-1">AI 动态 · 2026-11-11 <a class="header-anchor" href="#ai-动态-·-2026-11-11" aria-label="Permalink to &quot;AI 动态 · 2026-11-11&quot;">​</a></h1><blockquote><p>截至 2026-11-11。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>今日最大看点是 Google Gemini 4 Carbon 正式向所有开发者与企业开放，API 定价低于 Claude 同档模型，但 12 月 1 日将翻倍。</li><li>资本与监管面同样密集：Anthropic 七位联创在 IPO 中各套现约 2.5 亿美元，纽约 AI 安全法生效要求头部厂商登记与事故上报。</li><li>产品侧 ChatGPT 上线可验证的 Business Agents，开发者工具则聚焦 Agent 评测与 Git 安全补丁，前端今日无强相关硬新闻。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="anthropic-七位联创-ipo-中各套现约-2-5-亿美元" tabindex="-1">Anthropic 七位联创 IPO 中各套现约 2.5 亿美元 <a class="header-anchor" href="#anthropic-七位联创-ipo-中各套现约-2-5-亿美元" aria-label="Permalink to &quot;Anthropic 七位联创 IPO 中各套现约 2.5 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/821bebbeefa3.jpg" alt="配图"></p><p>TechCrunch 报道，Anthropic 七位联合创始人计划在 IPO 中卖出完全相同数量的股份，按发行价区间中值计算每人约套现 2.5 亿美元，同时该创始人群体仍保持对公司的控制权。这一安排在大规模 IPO 中并不常见，等额减持通常用于对外传递团队一致性信号。对读者：关注其招股书中的控制权条款与锁定期，这决定上市后治理结构与股价波动的节奏。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/10/all-7-anthropic-founders-will-each-cash-out-about-250m-in-ipo/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic-ipo-路演视频披露算力策略-四大芯片家族并用" tabindex="-1">Anthropic IPO 路演视频披露算力策略：四大芯片家族并用 <a class="header-anchor" href="#anthropic-ipo-路演视频披露算力策略-四大芯片家族并用" aria-label="Permalink to &quot;Anthropic IPO 路演视频披露算力策略：四大芯片家族并用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-11">2026-11-11</time></p><p>Simon Willison 整理了 Anthropic IPO 路演视频内容，其中联合创始人 Tom Brown 谈「算力路径」的部分包含此前未公开的信息：Anthropic 在 AWS Trainium、Google TPU、NVIDIA GPU 和 AMD GPU 四类芯片上训练并服务 Claude。作者用 MacWhisper 提取了非官方文字稿。对读者：多云多芯片已是前沿实验室的默认姿势，自建推理集群时应把「可移植性」列为架构硬约束。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/11/anthropic-ipo-roadshow/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="纽约-ai-安全法生效-openai、anthropic-面临新监管" tabindex="-1">纽约 AI 安全法生效，OpenAI、Anthropic 面临新监管 <a class="header-anchor" href="#纽约-ai-安全法生效-openai、anthropic-面临新监管" aria-label="Permalink to &quot;纽约 AI 安全法生效，OpenAI、Anthropic 面临新监管&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/1841fca8242c.webp" alt="配图"></p><p>TechCrunch 报道，纽约州开始执行其全面的 AI 安全法，要求 OpenAI、Anthropic 等主要开发商进行登记、披露安全实践，并上报重大事故，否则面临罚款。这意味着美国州层面的 AI 合规从立法进入执法阶段，头部厂商需建立常态化的报告流程。对读者：向美国市场提供模型服务的企业应尽早梳理登记义务与事故上报链路，别等收到问询才补。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/10/openai-anthropic-face-new-oversight-as-new-yorks-ai-safety-law-takes-effect/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-收购-sonder-创始人创办的旅游初创-odessia" tabindex="-1">OpenAI 收购 Sonder 创始人创办的旅游初创 Odessia <a class="header-anchor" href="#openai-收购-sonder-创始人创办的旅游初创-odessia" aria-label="Permalink to &quot;OpenAI 收购 Sonder 创始人创办的旅游初创 Odessia&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/b0173b13e28c.jpg" alt="配图"></p><p>TechCrunch 报道 OpenAI 已收购旅游初创公司 Odessia，其创始人是 Sonder 创始人 Francis Davidson，在旅游行业知名度较高。OpenAI 尚未说明对旅游业务的后续计划，这笔收购的动机与整合方向仍不明确。对读者：可留意 OpenAI 是否把旅游作为 Agent 落地的高频场景，这对做垂直 Agent 的团队是竞争信号。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/10/openai-acquires-odessia-travel-startup-created-by-sonder-founder/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="mercor-完成-7-5-亿美元-d-轮-估值-200-亿美元、年化-30-亿美元" tabindex="-1">Mercor 完成 7.5 亿美元 D 轮，估值 200 亿美元、年化 30 亿美元 <a class="header-anchor" href="#mercor-完成-7-5-亿美元-d-轮-估值-200-亿美元、年化-30-亿美元" aria-label="Permalink to &quot;Mercor 完成 7.5 亿美元 D 轮，估值 200 亿美元、年化 30 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Latent Space</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/499ca4145c89.png" alt="配图"></p><p>Latent Space 的 AI 日报提到 Mercor 完成 7.5 亿美元 D 轮融资，估值达 200 亿美元，年化收入 30 亿美元；同日 Google 正式开放 Gemini 4 Carbon。数据标注与专家数据赛道在模型竞赛中持续获得高估值，与模型价格战形成有趣对照。对读者：若你在做数据侧生意，可对照 Mercor 的「专家网络 + 平台化」路径检查自身定位。</p><p class="news-entry-source"><a href="https://latent.space/p/ainews-mercor-750m-series-d-at-20b-valuation-3b-run-rate/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="chatgpt-上线可验证的-ai「business-agents」" tabindex="-1">ChatGPT 上线可验证的 AI「Business Agents」 <a class="header-anchor" href="#chatgpt-上线可验证的-ai「business-agents」" aria-label="Permalink to &quot;ChatGPT 上线可验证的 AI「Business Agents」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/066295de70e6.png" alt="配图"></p><p>ChatGPT 将允许用户与代表品牌的、经过验证的「Business Agents」对话，首批面向美国「符合条件」的电商与在线服务企业，属于今日公布的一批面向企业的 beta 功能。当某企业创建了 Business Agent 并出现在 ChatGPT 回复中，用户即可与其对话，询问产品差异等追问。对读者：做电商或 SaaS 的品牌应尽早认领并配置 Agent，抢占 AI 搜索入口的解释权。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1030552/openai-chatgpt-business-agents-hub" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-允许商家在-chatgpt-中认领企业并配置销售-agent" tabindex="-1">OpenAI 允许商家在 ChatGPT 中认领企业并配置销售 Agent <a class="header-anchor" href="#openai-允许商家在-chatgpt-中认领企业并配置销售-agent" aria-label="Permalink to &quot;OpenAI 允许商家在 ChatGPT 中认领企业并配置销售 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VentureBeat AI</span><time datetime="2026-11-11">2026-11-11</time></p><p>VentureBeat 报道 OpenAI 开放商家在 ChatGPT 中「认领」自己的企业，并可设置一个定制的、具备代理能力的 AI 客户销售代表。这与 ChatGPT 的 Business Agents 功能相呼应，把品牌在对话式入口中的存在变成可配置资产。对读者：认领流程通常涉及资质审核，建议提前准备企业验证材料，避免上线窗口期落后于竞品。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMiywFBVV95cUxPR1k2TE9PS2pnenpoREV0aWhNbFJWeFFRbFBIWEF2dzBxNTdJS2RtenhLZUF6dWxwejg3SnBxRVYtSUxmdUlQUXUzcjgxdXY4TjNqMVJVNGVWOTNFWl83NGhYTEkydkN0Q1RMbEpISl85V0RrT0VtSmN1bnQ2MURLa2VQMjJyUVlnNkFkSTF0YzZ5NlJEZTBjZXpIdzNzX21Fc3otZzNyUVNNU2RWcjNwYzZVMVByOFlZeVFGd21tdGFBZXlUWkF0R1FXNA?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic-推出自家-ai-办公套件-瞄准白领与-ipo-前叙事" tabindex="-1">Anthropic 推出自家 AI 办公套件，瞄准白领与 IPO 前叙事 <a class="header-anchor" href="#anthropic-推出自家-ai-办公套件-瞄准白领与-ipo-前叙事" aria-label="Permalink to &quot;Anthropic 推出自家 AI 办公套件，瞄准白领与 IPO 前叙事&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/4f2344d2470d.jpg" alt="配图"></p><p>The Verge 报道 Anthropic 在旧金山活动上发布面向非技术知识工作者的 AI 办公工具套件，覆盖会议、头脑风暴与指标分析等场景。文章指出该公司长期以企业和编码工具见长，Claude Code 今年经历了一轮热度周期，如今正借 IPO 前的时间窗扩展用户面。对读者：评估办公套件时重点看它与现有文档/会议系统的集成深度，而非单点生成质量。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1030709/anthropic-has-its-own-ai-powered-office-suite-now" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="adobe-展示-ai-实验-走进照片、访谈角色" tabindex="-1">Adobe 展示 AI 实验：走进照片、访谈角色 <a class="header-anchor" href="#adobe-展示-ai-实验-走进照片、访谈角色" aria-label="Permalink to &quot;Adobe 展示 AI 实验：走进照片、访谈角色&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/b9653ccf966b.jpg" alt="配图"></p><p>The Verge 报道 Adobe 在年度 Max 大会上公布多项实验性功能：把图片转成可探索的 3D 场景、通过对话设计 AI 角色性格、以及把修图变成复制粘贴式操作。其中 Project Screen Test 用于让创作者与 AI 生成角色对话以塑造其人格，服务于视频内容制作。对读者：这些多为实验项目，适合做创意预研，不建议现在排进生产管线。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1031505/adobe-max-2026-sneaks-experiments-ai" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-向退伍军人与现役军人提供一年免费-chatgpt-plus" tabindex="-1">OpenAI 向退伍军人与现役军人提供一年免费 ChatGPT Plus <a class="header-anchor" href="#openai-向退伍军人与现役军人提供一年免费-chatgpt-plus" aria-label="Permalink to &quot;OpenAI 向退伍军人与现役军人提供一年免费 ChatGPT Plus&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/fbceeaeb07ac.webp" alt="配图"></p><p>OpenAI 宣布已有超过 2 万名退伍军人和转业服役人员领取了为期一年的免费 ChatGPT Plus，并展示了他们如何用其准备平民职业转型。这是 OpenAI 面向特定群体的一次公益性质投放，同时也是一次用户增长与品牌叙事动作。对读者：面向特定人群的免费额度常伴随资格审核，若你服务类似群体可参考其领取与转化路径。</p><p class="news-entry-source"><a href="https://openai.com/index/chatgpt-plus-for-veterans" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="gemini-4-carbon-正式向所有开发者与企业开放" tabindex="-1">Gemini 4 Carbon 正式向所有开发者与企业开放 <a class="header-anchor" href="#gemini-4-carbon-正式向所有开发者与企业开放" aria-label="Permalink to &quot;Gemini 4 Carbon 正式向所有开发者与企业开放&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/5f77d604dcae.jpg" alt="配图"></p><p>Google DeepMind 宣布 Gemini 4 Carbon 从面向「部分网络安全防御者」的限量开放转为向开发者、企业和消费者全面可用。此前两周的预热以安全场景为主，如今普通用户也能调用这一被 Google 称为「史上最强 Gemini」的模型。对读者：若计划接入，注意价格窗口期，尽早压测真实业务负载再决定是否长期绑定。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/gemini-4-carbon-is-now-available/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="头条-·-llm-gemini-0-36-跟进-gemini-4-carbon-2-10-起-12-月-1-日翻倍" tabindex="-1">头条 · llm-gemini 0.36 跟进 Gemini 4 Carbon：$2/$10 起，12 月 1 日翻倍 <a class="header-anchor" href="#头条-·-llm-gemini-0-36-跟进-gemini-4-carbon-2-10-起-12-月-1-日翻倍" aria-label="Permalink to &quot;头条 · llm-gemini 0.36 跟进 Gemini 4 Carbon：$2/$10 起，12 月 1 日翻倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/aad81b9094e4.webp" alt="配图"></p><p>Simon Willison 发布 llm-gemini 0.36，插件已支持全面开放的 Gemini 4 Carbon。文中给出关键定价：上线价每百万 token 输入 2 美元、输出 10 美元，与 GPT-6.1 Sol、Claude Sonnet 5.5 同档，但 12 月 1 日起翻倍至 4/20 美元，对齐 Opus 5.5。作者还用低、中、高三档 thinking effort 做了对比测试。对读者：成本敏感型应用应把 12 月 1 日当作预算分界线，提前评估切换或缓存策略。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/10/llm-gemini/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="gemini-4-carbon-公开可用-api-价格低于-claude-fable-5-2-与-opus-5-5" tabindex="-1">Gemini 4 Carbon 公开可用，API 价格低于 Claude Fable 5.2 与 Opus 5.5 <a class="header-anchor" href="#gemini-4-carbon-公开可用-api-价格低于-claude-fable-5-2-与-opus-5-5" aria-label="Permalink to &quot;Gemini 4 Carbon 公开可用，API 价格低于 Claude Fable 5.2 与 Opus 5.5&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VentureBeat AI</span><time datetime="2026-11-11">2026-11-11</time></p><p>VentureBeat 报道 Gemini 4 Carbon 已面向公众开放，并强调其在 API 定价上低于 Claude Fable 5.2 和 Opus 5.5。这与 Google 一贯以价格切入企业市场的策略一致，也让前沿模型之间的单位成本竞争进一步加剧。对读者：做模型选型时把「上线价 vs 后续价」两列都算进 TCO，避免被短期促销价误导。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="deepmind-发布-alphagenome-2-解读细胞如何读取-dna" tabindex="-1">DeepMind 发布 AlphaGenome 2：解读细胞如何读取 DNA <a class="header-anchor" href="#deepmind-发布-alphagenome-2-解读细胞如何读取-dna" aria-label="Permalink to &quot;DeepMind 发布 AlphaGenome 2：解读细胞如何读取 DNA&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-11-11">2026-11-11</time></p><p>Google DeepMind 推出 AlphaGenome 2，用于预测 DNA 序列及其变异如何影响特定人类细胞类型与疾病。它是去年发布的基因组预测模型 AlphaGenome 的继任者，目标是把「同一套 DNA 在不同细胞中产生不同结果」这一难题做得更细。对读者：生物医药方向的团队可关注其论文与开放接口，评估在靶点发现与变异解读流程中的可用性。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/alphagenome-2-deciphering-how-cells-read-dna-to-better-understand-disease/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="alphagenome-2-聚焦疾病的细胞根源" tabindex="-1">AlphaGenome 2 聚焦疾病的细胞根源 <a class="header-anchor" href="#alphagenome-2-聚焦疾病的细胞根源" aria-label="Permalink to &quot;AlphaGenome 2 聚焦疾病的细胞根源&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/33336583bbe6.jpg" alt="配图"></p><p>The Verge 报道 DeepMind 新模型 AlphaGenome 2 的设计目标：揭示 DNA 变化如何影响不同细胞，从而为疾病成因与新疗法提供线索。文章指出人体几乎所有细胞携带相同 DNA，但心肌细胞等不同类型细胞的读取方式不同，这正是模型要建模的部分。对读者：这是 AI for Science 的长期赛道，短期不必追热点，但值得订阅其后续评测数据。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1031524/google-deepmind-alphagenome-2-genetic-ai-model" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="aws-开源-uaef-跨框架的-agent-闭环评测系统" tabindex="-1">AWS 开源 UAEF：跨框架的 Agent 闭环评测系统 <a class="header-anchor" href="#aws-开源-uaef-跨框架的-agent-闭环评测系统" aria-label="Permalink to &quot;AWS 开源 UAEF：跨框架的 Agent 闭环评测系统&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-11-11">2026-11-11</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/77e54061d1e0.png" alt="配图"></p><p>AWS 介绍 Universal Agent Evaluation Framework（UAEF），一个与框架无关的 AI Agent 评测系统。它把各框架的 trace 转成统一格式，用覆盖 7 个维度的 36 项内置指标打分并存储结果，便于团队对比 Agent 版本、捕捉回归。对读者：Agent 上线前最缺的正是可比的回归基线，可先用它统一评测口径再谈调优。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/uaef-a-framework-agnostic-system-for-closed-loop-evaluation-of-ai-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',9)])])}const g=a(s,[["render",i]]);export{m as __pageData,g as default};
